var assert         = require("assert");
var TafMonitor     = require("@taf/taf-monitor");
var TimeProvider   = require("@taf/taf-utils").timeProvider;
var TafError       = require("../util/TafError.js").TafError;
var RpcCallError   = require("../util/RpcCallError.js").RpcCallError;
var TQueue         = require("../util/TQueue.js").TQueue;
var TCPTransceiver = require("./Transceiver.js").TCPTransceiver;
var UDPTransceiver = require("./Transceiver.js").UDPTransceiver;
var ReqMessage     = require("./ReqMessage.js").ReqMessage;
var CommonTool     = require("../util/CommTool");
var TafStream      = require('@taf/taf-stream');

/**
 * 超时一定比率后进行切换
 * 设置超时检查参数
 * 计算到某台服务器的超时率, 如果连续超时次数或者超时比例超过阀值
 * 默认60s内, 超时调用次数>=2, 超时比率0.5或者连续超时次数>5,
 * 则失效
 * 服务失效后, 请求将尽可能的切换到其他可能的服务器, 并每隔tryTimeInterval尝试一次, 如果成功则认为恢复
 * 如果其他服务器都失效, 则随机选择一台尝试
 * 如果是灰度状态的服务, 服务失效后如果请求切换, 也只会转发到相同灰度状态的服务
 * @uint16_t minTimeoutInvoke, 计算的最小的超时次数, 默认2次(在checkTimeoutInterval时间内超过了minTimeoutInvoke, 才计算超时)
 * @uint32_t frequenceFailInvoke, 连续失败次数
 * @uint32_t checkTimeoutInterval, 统计时间间隔, (默认60s, 不能小于30s)
 * @float radio, 超时比例 > 该值则认为超时了 ( 0.1<=radio<=1.0 )
 * @uint32_t tryTimeInterval, 重试时间间隔
 */

//////////////////////////////////////////////定义接口代理类////////////////////////////////////////////////////////////
var AdapterProxy = function () {
    this._worker                = undefined;        //所属的ObjectProxy
    this._endpoint              = undefined;        //服务端的IP地址以及端口
    this._pTrans                = undefined;        //连接服务端的套接口

    this._pTimeoutQueueY        = new TQueue();     //当前端口上的已发送调用队列
    this._pTimeoutQueueN        = new TQueue();     //当前端口上的未发送调用队列

    this._activeStatus          = true;             //当前端口上的可用状态
    this._nextFinishInvokeTime  = 0;                //下次检测调用统计的时间点
    this._nextReconnectTime     = 0;                //非活跃节点下次重连时间(对端连接卡在半连接或者无法正常处理请求时会触发)
    this._nextRetryTime         = 0;                //下次尝试重连的时间
    this._frequenceFailTime     = 0;                //检测连续调用失败的时间点
    this._frequenceFailInvoke   = 0;                //连续调用失败次数
    this._totalInvoke           = 0;                //总共调用次数
    this._timeoutInvoke         = 0;                //调用失败次数
    this._connExc               = false;            //连接异常，false：没有异常；true：异常
    this._stopKeepAliveFunc     = undefined;        //保持长连定时任务终止函数
    this._bStartKeepAlive       = false;            //开启keepalive定时器标识
};
module.exports.AdapterProxy = AdapterProxy;

//设置接口代理类对外暴露的属性
AdapterProxy.prototype.__defineGetter__("worker",   function () { return this._worker; });
AdapterProxy.prototype.__defineSetter__("worker",   function (value) { this._worker = value;   });

AdapterProxy.prototype.__defineGetter__("endpoint", function () { return this._endpoint; });
AdapterProxy.prototype.__defineSetter__("endpoint", function (value) { this._endpoint = value; });

AdapterProxy.prototype.__defineGetter__("connExc", function () { return this._connExc; });
AdapterProxy.prototype.__defineSetter__("connExc", function (value) { this._connExc = value; });

AdapterProxy.prototype.pushTimeoutQueueN = function(reqMessage)
{
    this._pTimeoutQueueN.push(reqMessage.request.iRequestId, reqMessage);
};

AdapterProxy.prototype.pushTimeoutQueueY = function(reqMessage)
{
    this._pTimeoutQueueY.push(reqMessage.request.iRequestId, reqMessage);
};

//初始化代理类，主要生成网络传输类的实例
AdapterProxy.prototype.initialize = function () {
    assert(this._endpoint.sProtocol === "tcp" || this._endpoint.sProtocol === "udp", "trans protocol must be tcp or udp");
    if (this._endpoint.sProtocol === "tcp") {
        this._pTrans = new TCPTransceiver(this, this._endpoint);
    } else {
        this._pTrans = new UDPTransceiver(this, this._endpoint);
    }
};

AdapterProxy.prototype.sendKeepAlive = function(){
    if(this._worker && this._worker.bKeepAlive && this._pTrans){
        var os = new TafStream.JceOutputStream();
        var property = {
            ignorePromise: true,   //忽略promise
            ignoreTimeout: true    //忽略超时
        }
        var reqMessage = this._worker.compose('taf_ping', os.getBinBuffer(), property, 2);
        reqMessage.adapter = this;
        reqMessage.RemoteEndpoint = this._endpoint;
        this._pTrans.sendRequest(reqMessage.request);
    }
}

//保持心跳的定时任务
AdapterProxy.prototype.keepAliveTask = function(){
    if(this._bStartKeepAlive){
        return;
    }
    var self = this;
    if(this._worker && this._worker.bKeepAlive &&  this._worker.iHeartInterval > 0){
        this._stopKeepAliveFunc = CommonTool.simulateInterval(function(){self.sendKeepAlive();}, this._worker.iHeartInterval);
        this._bStartKeepAlive = true; 
    }
}

//将队列返还给ObjectProxy，并调用worker的doInvoke，以选择其他节点重新发送
//如果不返还请求数据，请求量很大，干掉某个节点的时候，此节点中的请求可能会超时
AdapterProxy.prototype._resetQueue=function(){
    var self=this;
    var worker=self.worker;
    if(self._worker._bRetryOnDestroy){
        self._pTimeoutQueueY.forEach(function (key) {
            var reqMessage = self._pTimeoutQueueY.pop(key, true);
            delete reqMessage.adapter;
            delete reqMessage.RemoteEndpoint;
            reqMessage.location = 1;
            worker.pTimeoutQueue.push(reqMessage.request.iRequestId, reqMessage);
        });
    }
    self._pTimeoutQueueN.forEach(function (key) {
        var reqMessage = self._pTimeoutQueueN.pop(key, true);
        delete reqMessage.adapter;
        delete reqMessage.RemoteEndpoint;
        reqMessage.location = 1;
        worker.pTimeoutQueue.push(reqMessage.request.iRequestId, reqMessage);
    });
    process.nextTick(function(){
        worker.doInvoke();
    });
}

// 销毁当前的连接代理类，在如下的时机：
// 第一，该服务端被从主控去除之后
// 第二，关闭当前的连接
AdapterProxy.prototype.destroy = function () {
    var self = this;
    self._resetQueue();
    if(self._stopKeepAliveFunc){
        self._stopKeepAliveFunc();
    }
    //加上延时关闭逻辑，处理无损重启时仍然可以正常应答的调用
    //此时节点已经从endpoint列表移除，不会再接收新的请求，只会等待已发送的请求返回并处理
    setTimeout(function () {
        self._pTimeoutQueueY.clear();
        self._pTrans.close();
    }, self._worker.timeout)
};

//请求返回了，并且Transceiver获得了一个完整的请求，由Transceiver回调该接口
AdapterProxy.prototype.doResponse = function ($rspMessage) {
    if ($rspMessage.iRequestId != 0) {
        var reqMessage = this._pTimeoutQueueY.pop($rspMessage.iRequestId, true);
        //如果在当前已发送队列中没有发现该请求，有可能是因为超时被删除了,或者是单向请求压根没加入队列
        if (reqMessage === undefined) {
            return;
        }

        reqMessage.LocalEndpoint  = this._pTrans.LocalEndpoint;
        reqMessage.clearTimeout();
        reqMessage.adapter.finishInvoke($rspMessage.origin.iRet, reqMessage);

        $rspMessage.origin.costtime = reqMessage.costtime;

        if ($rspMessage.origin.iRet === 0) {
            reqMessage.promise.resolve({ request: ReqMessage.getReqInfo(reqMessage), response: $rspMessage.origin });
        } else {
            reqMessage.promise.reject(new RpcCallError({ request: ReqMessage.getReqInfo(reqMessage), response: $rspMessage.origin, error: { code: $rspMessage.origin.iRet, message: $rspMessage.origin.sResultDesc } }));
        }

    } else {
        if (this._worker._pushCallback) {
            this._worker._pushCallback($rspMessage);
        }

    }
};

//当在AdapterProxy内队列上的请求超时的时候，调用当前函数
AdapterProxy.prototype.doTimeout = function ($reqMessage) {
    // 有可能在任一队列上，无论那种情况尝试删除即可
    this._pTimeoutQueueY.erase($reqMessage.request.iRequestId);
    this._pTimeoutQueueN.erase($reqMessage.request.iRequestId);

    $reqMessage.clearTimeout();
    $reqMessage.adapter.finishInvoke(TafError.CLIENT.REQUEST_TIMEOUT, $reqMessage);
    $reqMessage.LocalEndpoint  = this._pTrans.LocalEndpoint;

    var errMsg = "call remote server timeout(remote server no response)";

    if (this._endpoint && this._endpoint.toString) {
      errMsg = "call remote server timeout(remote server@" + this._endpoint.toString() + " no response)";
    }

    $reqMessage.promise.reject(new RpcCallError({
      request: ReqMessage.getReqInfo($reqMessage),
      response: undefined,
      error: {
          code: TafError.CLIENT.REQUEST_TIMEOUT,
          message: errMsg
      }
  }));
};

//发送积压的数据
//当前代理类重新连接或者第一次连接上对端服务之后，回调该函数
AdapterProxy.prototype.doInvoke = function () {
    //遍历未发送的请求
    var self = this;
    self._pTimeoutQueueN.forEach(function (key) {
        var reqMessage = self._pTimeoutQueueN.pop(key, true);

        if (self._pTrans.sendRequest(reqMessage.request)) {
            //单向请求不需要向请求成功队列里边加入数据，而是立即reject
            if(reqMessage.request.property && reqMessage.request.property.packetType === 1){
                reqMessage.adapter._doOneWayEnd(reqMessage);
            }
            else{
                self._pTimeoutQueueY.push(reqMessage.request.iRequestId, reqMessage);
            }
        } else {
            self._doInvokeException(reqMessage);
        }
    });

    //看ObjectProxy上是否有数据需要发送
    self._worker.doInvoke();
};

//单向请求发送成功后即调用此函数，避免请求数据长时间在_pTimeoutQueueY队列中直到超时，占用内存
AdapterProxy.prototype._doOneWayEnd = function (reqMessage) {
    reqMessage.clearTimeout();
    //标记一下调用成功，避免触发节点失活策略
    reqMessage.adapter.finishInvoke(0, reqMessage);
    reqMessage.promise.reject(new RpcCallError({ request: ReqMessage.getReqInfo(reqMessage), response: undefined, error:{ code: reqMessage.iResultCode, message: "one way call do not need response" } }));
}
// 从当前积压队列中再次发送数据时失败，则不再尝试，直接作为异常处理
AdapterProxy.prototype._doInvokeException = function ($reqMessage) {
    $reqMessage.clearTimeout();
    $reqMessage.adapter.finishInvoke(TafError.CLIENT.ADAPTER_NOT_FOUND, $reqMessage);

    $reqMessage.promise.reject(new RpcCallError({ request: ReqMessage.getReqInfo($reqMessage), response: undefined, error: { code: TafError.CLIENT.ADAPTER_NOT_FOUND, message: "call remote server error(send again error)" } }));
};

AdapterProxy.prototype.invoke = function ($reqMessage) {
    this.keepAliveTask();
    $reqMessage.adapter = this;
    $reqMessage.RemoteEndpoint = this._endpoint;

    if (this._pTrans.sendRequest($reqMessage.request)) {
        if($reqMessage.request.property && $reqMessage.request.property.packetType === 1){
            //单向请求不需要向请求成功队列里边加入数据
            $reqMessage.adapter._doOneWayEnd($reqMessage);
        }
        else{
            //如果非单向请求发送成功，则放入发送成功队列
            this._pTimeoutQueueY.push($reqMessage.request.iRequestId, $reqMessage);
        }
    } else {
        this._pTimeoutQueueN.push($reqMessage.request.iRequestId, $reqMessage); //如果发送失败，则放入发送失败队列，稍后尝试再次发送
    }
};

//设置当前代理类为无效
AdapterProxy.prototype._setInactive = function () {
    var nowTime = TimeProvider.nowTimestamp();
    this._activeStatus  = false;
    this._nextRetryTime = nowTime + this._worker._checkTimeoutInfo.tryTimeInterval;
    this._nextReconnectTime = nowTime + this._worker._checkTimeoutInfo.reconnectInterval;
    this._pTrans.close();
};

//判断当前的接口代理实例是否可用
AdapterProxy.prototype.checkActive = function ($bForceConnect) {
    //连接成功，直接返回可用；连接中，在后面的逻辑中判断是否在重试区间。
    //这里不能去掉连接状态判断，不然异常节点重连时，会被重试时间拦住，导致其恢复时间延后一个等待周期
    if (this._pTrans.hasConnected()) {
        return true;
    }

    var nowTime = TimeProvider.nowTimestamp();

    //如果是需要强制连接
    if ($bForceConnect) {
        this._nextRetryTime = nowTime + this._worker._checkTimeoutInfo.tryTimeInterval;
        if (!this._pTrans.isValid()) {
            this._pTrans.reconnect();
        }
        return this._pTrans.hasConnected();
    }
    //失效且没有到下次重试时间, 直接返回不可用
    if (!this._activeStatus && nowTime < this._nextRetryTime) {
        return false;
    }

    //如果还没有连接过，那么就重新连接
    if (!this._pTrans.isValid()) {
        this._pTrans.reconnect();
    }

    if (!this._activeStatus) {
        this._nextRetryTime = nowTime + this._worker._checkTimeoutInfo.tryTimeInterval;
    }

    //返回当前AdapterProxy是否可用
    //正常情况下，当已经连接成功（状态为ES_CONNECTED）的时候，才返回连接ok
    return this._pTrans.hasConnected();
};

//处理当前代理类有效性的检查等功能
AdapterProxy.prototype._doFinishInvoke = function ($iResultCode) {
    var nowTime = TimeProvider.nowTimestamp();

    //处于异常状态
    if (this._activeStatus === false) {
        if ($iResultCode === 0) { //调用成功的情况下，重置统计数据
            this._activeStatus          = true;
            this._frequenceFailInvoke   = 0;
            this._totalInvoke           = 1;
            this._timeoutInvoke         = 0;
            this._nextFinishInvokeTime  = nowTime + this._worker._checkTimeoutInfo.checkTimeoutInterval;
        } else {
            //这里再次断开节点，处理连接一直没有真正断开的情况
            if (nowTime > this._nextReconnectTime){
                this._nextReconnectTime = nowTime + this._worker._checkTimeoutInfo.reconnectInterval;
                this._setInactive();
            }
            console.error("_doFinishInvoke, errorCode=", $iResultCode, ",server=", this._worker.name, ",endpoint=" ,this._endpoint.toString());
        }
        return ;
    }

    //处于正常状态
    this._totalInvoke++;

    if ($iResultCode !== 0) { //调用失败
        this._timeoutInvoke++;
        if (this._frequenceFailInvoke === 0) {
            this._frequenceFailTime = nowTime + this._worker._checkTimeoutInfo.minFrequenceFailTime;
        }
        this._frequenceFailInvoke++;

        //检查是否到了连续失败次数,且至少在5ms以上
        if (this._frequenceFailInvoke >= this._worker._checkTimeoutInfo.frequenceFailInvoke && nowTime >= this._frequenceFailTime) {
            this._setInactive();
        }
    } else { //调用成功
        this._frequenceFailInvoke = 0;
    }

    //判断一段时间内的超时比例
    if (nowTime > this._nextFinishInvokeTime) {
        this._nextFinishInvokeTime = nowTime + this._worker._checkTimeoutInfo.checkTimeoutInterval;
        if ($iResultCode !== 0 && this._timeoutInvoke >= this._worker._checkTimeoutInfo.minTimeoutInvoke && this._timeoutInvoke >= parseInt(this._worker._checkTimeoutInfo.radio * this._totalInvoke)) {
            this._setInactive();
        } else {
            this._totalInvoke   = 0;
            this._timeoutInvoke = 0;
        }
    }
};

AdapterProxy.prototype.finishInvoke = function ($iResultCode, $reqMessage) {
    $reqMessage = $reqMessage || {};
    //若在node-agent中运行时，若设置了调用完毕消息同步，将调用完成的消息在各工作进程间同步
    if(this._worker._bSyncInvokeFinish){
        process.send({
            cmd         : "process.msg:all",
            event       : "finishInvoke",
            objname     : this._worker._objname,
            setname     : this._worker._setname,
            endpoint    : this._endpoint,
            iResultCode : $iResultCode
        });
    }
    else{
        this._doFinishInvoke($iResultCode);
    }
    var packetType = 0;
    if($reqMessage.request.property && $reqMessage.request.property.packetType === 1)
        packetType = 1;

    //如果是在正式环境，则上报统计信息(单向调用不需要上报), wup由于在服务端上报，客户端也不做上报
    if (process.env.TAF_MONITOR && packetType !== 1 && $reqMessage.worker.version == 1) {
        //正式环境需要上报统计数据

        var masterSetInfo = '', masterContainer = '', slaveContainer = '', masterModuleName = '';
        var arr = [], slaveSetName = '', slaveSetArea = '', slaveSetID = '', servantArr;
        var communicator = this._worker._comm;
        var masterConfig = communicator.configure;

        masterModuleName = masterConfig.get("taf.application.client.modulename", '');

        var enableSet = masterConfig.get("taf.application.enableset", 'n');

        if(enableSet == 'y' || enableSet == 'Y')
        {
            var setDivision = masterConfig.get("taf.application.setdivision", undefined);
            if(setDivision)
            {
                masterSetInfo = setDivision;
                arr = setDivision.split(".");
                masterModuleName += '.' + arr.join('');
            }
        }

        var servantName = $reqMessage.request.sServantName;
        arr = servantName.split('.');
        arr = arr.slice(0, 2);
        servantName = arr.join('.');

        var setId       = $reqMessage.request.setId;

        var headers = {
            masterName    : masterModuleName,
            slaveName     : servantName,
            interfaceName : $reqMessage.request.sFuncName,
            masterIp      : this._worker.communicator.ClientConfig.LocalIp,
            slaveIp       : this._endpoint.sHost,
            slavePort     : this._endpoint.iPort,
            bFromClient   : true
        };

        if(setId)
        {
            servantArr = servantName.split('.');

            arr = setId.split(".");
            if(arr && arr.length >= 3)
            {
                slaveSetName         = arr[0];
                slaveSetArea         = arr[1];
                slaveSetID           = arr[2];

                headers.slaveName    = servantArr[0] + '.'+ servantArr[1] + '.' + arr.join('');

                headers.slaveSetName = slaveSetName;
                headers.slaveSetArea = slaveSetArea;
                headers.slaveSetID   = slaveSetID;
            }
        }


        if(masterSetInfo)
            headers.masterSetInfo = masterSetInfo;

        if(masterContainer)
            headers.masterContainer = masterContainer;


        if(!($reqMessage.costtime >= 0) || !isFinite($reqMessage.costtime))
        {
            $reqMessage.costtime = 0;
        }

        if ($iResultCode === 0 && $reqMessage === undefined) {
            TafMonitor.stat.report(headers, TafMonitor.stat.TYPE.SUCCESS, 0);
        }

        if ($iResultCode === 0 && $reqMessage !== undefined) {
            TafMonitor.stat.report(headers, TafMonitor.stat.TYPE.SUCCESS, $reqMessage.costtime);
        }

        if ($iResultCode !== 0 && $reqMessage === undefined) {
            TafMonitor.stat.report(headers, TafMonitor.stat.TYPE.ERROR, 0);
        }

        if ($iResultCode !== 0 && $reqMessage !== undefined) {
            TafMonitor.stat.report(headers, $iResultCode === TafError.CLIENT.REQUEST_TIMEOUT?TafMonitor.stat.TYPE.TIMEOUT:TafMonitor.stat.TYPE.ERROR, $reqMessage.costtime);
        }
    }
};
